  "parcours.cohortes.ecart_gf": "écart garçons − filles",
  "parcours.rattrapage.title": "Qui rattrape, qui décroche ?",
  "parcours.rattrapage.subtitle": "Accès au formel de la génération 25-59 vers la génération 15-24. Toutes les wilayas progressent : ce qui distingue, c'est de progresser assez vite pour rattraper.",
  "parcours.rattrapage.insuffisant": "rattrapage insuffisant",
  "parcours.rattrapage.ok": "rattrape ou dépasse",
  "parcours.rattrapage.lecture": "{n} wilaya(s) — {liste} — cumulent un niveau inférieur à la moyenne nationale des 15-24 ans ({nat} %) et un gain inférieur au gain médian ({med} pts) : leur retard se creuse en relatif. C'est un critère de priorité que l'IPE, qui mesure le stock, ne peut pas capter.",
  "Jamais scolarisé": "Jamais scolarisé",
