  "rendement.loading": "Calcul des rendements…",
  "rendement.eyebrow": "Pourquoi investir",
  "rendement.title": "Le rendement de l'école",
  "rendement.subtitle": "Le projet plaide pour l'école formelle sans jamais montrer ce qu'elle rapporte. Les variables de chômage et de pauvreté, croisées au niveau atteint, donnent une réponse — et elle est contre-intuitive.",
  "rendement.kpi.pauvrete": "Pauvreté",
  "rendement.kpi.pauvrete_sub": "non formel → formel, soit {n} points",
  "rendement.kpi.structure": "Rendement propre",
  "rendement.kpi.structure_sub": "part de l'écart non expliquée par le profil",
  "rendement.kpi.chomage": "Chômage",
  "rendement.kpi.chomage_sub": "jamais scolarisé → universitaire",
  "rendement.kpi.or": "Risque de pauvreté",
  "rendement.kpi.or_sub": "universitaire vs jamais scolarisé, toutes choses égales",
  "rendement.gradient.title": "Deux gradients opposés",
  "rendement.gradient.subtitle": "Le même axe des niveaux, deux résultats inverses. Les deux graphiques sont séparés : superposer deux échelles sur un seul axe fausserait la comparaison.",
  "rendement.gradient.pauvrete": "Taux de pauvreté par niveau atteint",
  "rendement.gradient.chomage": "Taux de chômage (BIT) par niveau atteint",
  "rendement.paradoxe.title": "Le paradoxe du chômage instruit",
  "rendement.paradoxe.text": "L'école formelle n'améliore pas le taux de chômage — elle l'augmente. C'est un effet de définition : au sens du BIT, est chômeur celui qui cherche un emploi. En milieu rural non scolarisé, on est occupé (agriculture, élevage, informel) donc pas « chômeur », et pauvre. Le diplôme fait entrer dans un marché du travail où l'on peut être en recherche — et où l'on est nettement moins pauvre.",
  "rendement.oaxaca.title": "Décomposition d'Oaxaca-Blinder",
  "rendement.oaxaca.subtitle": "L'écart de pauvreté vient-il de l'instruction elle-même, ou du fait que les personnes instruites sont par ailleurs plus urbaines et plus jeunes ? La décomposition sépare les deux.",
  "rendement.oaxaca.total": "Écart total",
  "rendement.oaxaca.composition": "Composition",
  "rendement.oaxaca.structure": "Structure",
  "rendement.oaxaca.lecture_cle": "La part « structure » est celle qu'un programme de scolarisation peut espérer capter : elle mesure le rendement propre de l'instruction, à caractéristiques identiques. La part « composition » rappelle qu'une partie de l'écart tient à qui sont les personnes instruites, et non à l'instruction elle-même.",
  "rendement.oaxaca.detail": "Détail de l'effet de composition",
  "rendement.oaxaca.detail_note": "Contribution de chaque caractéristique à la part « composition », en points de pourcentage de l'écart de pauvreté.",
  "rendement.var.rural": "Milieu rural",
  "rendement.var.feminin": "Sexe féminin",
  "rendement.var.age": "Âge",
  "rendement.var.age2": "Âge²",
  "rendement.var.wilaya": "Wilaya",
  "rendement.logit.title": "Risque de pauvreté ajusté, par niveau atteint",
  "rendement.logit.subtitle": "Odds-ratios de pauvreté, référence « {ref} ». Contrôles : {controles}. Une barre plus courte que le trait pointillé signifie un risque réduit.",
  "rendement.logit.lecture": "Estimé sur {n} individus de 15-64 ans, pseudo-R² de {r2}. Même à âge, sexe, milieu et wilaya identiques, chaque palier franchi réduit le risque de pauvreté — le gradient n'est donc pas un simple effet de composition.",
  "unit.pts": "pts",
  "unit.pt_an": "pt/an",
  "robustesse.mc.conclusion": "Sur {n} jeux de pondérations tirés au hasard autour des poids retenus, {k} wilayas sur {tot} gardent le même rang dans 90 % des tirages — dont les cinq premières, qui ne bougent jamais. L'instabilité se concentre au milieu du classement ({instables}), là où les écarts d'IPE sont de l'ordre du point. Les cinq méthodes d'agrégation s'accordent par ailleurs à ρ ≥ {rho} (Spearman) : la hiérarchie des priorités est une propriété des données, pas du choix de pondération.",
  "robustesse.ci.note": "Bootstrap non paramétrique (tirage simple avec remise sur les individus). Le fichier EPCV fourni ne contient ni identifiant de ménage, ni pondération, ni strate : l'effet de grappe n'est pas modélisé et ces intervalles sont donc une borne optimiste de l'incertitude réelle.",
  "robustesse.theil.lecture": "{inter} % de l'inégalité d'exclusion se joue entre les wilayas, {intra} % à l'intérieur de chacune (fracture urbain/rural). Un ciblage purement territorial ne peut donc pas atteindre la totalité du problème.",
  "robustesse.hoi.lecture": "{c} % des enfants de 6-14 ans ont accès à l'école formelle, mais une fois corrigée de l'inégalité des circonstances cette couverture ne « vaut » que {h} % : {p} points sont perdus du seul fait que l'accès dépend d'où et de qui l'on naît.",
  "robustesse.offre.lecture": "Il faudrait redéployer {db} % des établissements pour que l'offre épouse la carte du hors-école, contre {de} % pour qu'elle épouse simplement la carte des enfants : l'offre est mal alignée sur le besoin, pas seulement sur la population.",
  "robustesse.validation.explication": "Les deux mesures ne comptent pas la même chose. L'EPCV mesure ici les 6-14 ans n'étant jamais entrés à l'école formelle (la variable « dejall » montre qu'aucun enfant hors école de cette tranche n'y est entré puis sorti). Le WDI mesure les enfants d'âge primaire officiel hors école une année donnée. L'écart de 2 points sur une tranche d'âge plus large est cohérent.",
  "robustesse.validation.alerte": "La pente de {p1} pt/an qui alimente les scénarios 2030 repose presque entièrement sur la seule observation 2024 ({v2024} %, contre {v2020} % en 2020). Sans ce point, la tendance tombe à {p2} pt/an, soit une quasi-stagnation. Les projections doivent être lues comme un encadrement entre ces deux hypothèses, pas comme une prévision.",
  "robustesse.validation.uis": "Le fichier data/raw/unesco_uis_outofschool.csv ne contient pas de données : c'est la trace d'un échec de connexion à l'API UIS (résolution DNS). La validation externe repose donc uniquement sur le WDI.",
  "nav.robustesse": "Robustesse",
