  "robustesse.ci.subtitle": "Chaque taux est une estimation issue d'un échantillon inégal : 267 enfants en Inchiri contre 2 619 à Nouakchott. L'estimateur rétréci rapproche les petites wilayas de la moyenne nationale, proportionnellement à leur imprécision.",
