  "indicateurs.eyebrow": "Matrice de corr\u00e9lation \u00b7 Pearson",
  "indicateurs.heatmap_sub": "Vert = corr\u00e9lation n\u00e9gative, orange = positive, noir = neutre. Ne lisez que le triangle inf\u00e9rieur (l'image est sym\u00e9trique).",
  "indicateurs.heatmap_title": "Heatmap de corr\u00e9lation 12 indicateurs \u00d7 13 wilayas",
  "indicateurs.insight1.text": "Le taux hors \u00e9cole est port\u00e9 par la d\u00e9pendance jeunes (0-14 / 15-64), elle-m\u00eame adoss\u00e9e \u00e0 la ruralit\u00e9 : la famille rurale, nombreuse et pauvre est la cible structurelle.",
  "indicateurs.insight1.title": "La ruralit\u00e9 est le socle",
  "indicateurs.insight2.text": "La part de 0-14 ans et la d\u00e9pendance jeunes sont corr\u00e9l\u00e9es \u00e0 1.00 : ce n'est qu'un seul et m\u00eame d\u00e9terminant d\u00e9mographique, \u00e0 traiter comme un bloc.",
  "indicateurs.insight2.title": "Population jeune et d\u00e9pendance : jumeaux",
  "indicateurs.insight3.text": "Le genre n'appara\u00eet nulle part : il ne discrimine pas le hors \u00e9cole. De m\u00eame, le nombre d'\u00e9coles n'est pas le premier levier la distance et l'offre mahadra le sont.",
  "indicateurs.insight3.title": "Ce qui ne corr\u00e8le pas",
  "indicateurs.insight4.text": "Les r de 1.00 proviennent d'indicateurs construits l'un \u00e0 partir de l'autre : nous les \u00e9cartons des recommandations.",
  "indicateurs.insight4.title": "Attention aux corr\u00e9lations parfaites",
  "indicateurs.loading": "Calcul des corr\u00e9lations\u2026",
  "indicateurs.subtitle": "La matrice de corr\u00e9lation de 12 indicateurs (r de Pearson, couleur = force) r\u00e9v\u00e8le les d\u00e9terminants structurels. Une heatmap sym\u00e9trique, tri\u00e9e pour la lisibilit\u00e9.",
  "indicateurs.title": "Ce qui fait l'exclusion, ce qui ne la fait pas",
