  "methodologie.choix": "Choix m\u00e9thodologiques",
  "methodologie.choix1.k": "Un seul type d'\u00e9cole formelle",
  "methodologie.choix1.text": "La cat\u00e9gorie officielle \u00ab Coranique \u00bb (C4N=2) est agr\u00e9g\u00e9e \u00e0 la mahadra conforme au r\u00e9f\u00e9rentiel EduFocus. Un enfant en mahadra est \u00ab hors \u00e9cole formelle \u00bb mais instruit : l'effort porte sur les passerelles, pas l'alphab\u00e9tisation.",
  "methodologie.choix2.k": "Pond\u00e9ration 2019 \u2192 2022",
  "methodologie.choix2.text": "Les parts de l'EPCV 2019 sont appliqu\u00e9es aux pyramides 2022 par wilaya : les pourcentages deviennent des effectifs budg\u00e9tables.",
  "methodologie.choix3.k": "Normalisation min-max",
  "methodologie.choix3.text": "Chaque composante de l'IPE est normalis\u00e9e 0-100 avant pond\u00e9ration, pour rendre les trois dimensions comparables.",
  "methodologie.choix4.k": "Clusters interpr\u00e9tables",
  "methodologie.choix4.text": "k retenu par silhouette (k=3 : 0.331) pour un \u00e9quilibre entre lisibilit\u00e9 statistique et richesse des profils.",
  "methodologie.intensite": "Intensit\u00e9",
