  "methodologie.step1.d": "60 600 individus (SPSS) enqu\u00eate m\u00e9nages de l'ONS. Codage : situation scolaire, milieu, wilaya, pauvret\u00e9, sexe, \u00e2ge.",
  "methodologie.step1.t": "Microdonn\u00e9es EPCV 2019",
  "methodologie.step2.d": "\u00c9chantillon pond\u00e9r\u00e9 et projet\u00e9 sur la population wilaya par wilaya (2022, HDX / ONS) pour passer des pourcentages aux effectifs.",
  "methodologie.step2.t": "Projection d\u00e9mographique",
  "methodologie.step3.d": "Score 0-100 par wilaya : prioriser l\u00e0 o\u00f9 il y a beaucoup ET une forte proportion d'enfants exclus, dans un contexte vuln\u00e9rable.",
  "methodologie.step3.t": "Indice de Priorit\u00e9 \u00c9ducative (IPE)",
  "methodologie.step4.d": "k-moyennes normalis\u00e9es (k=3) : trois m\u00e9canismes d'exclusion distincts, chacun avec son levier d'action.",
  "methodologie.step4.t": "Typologie (clustering)",
  "methodologie.step5.d": "Similarit\u00e9 entre wilayas (top-2 voisins, r\u22650.85) et r\u00e9seau de corr\u00e9lations entre indicateurs (|r|\u22650.75).",
  "methodologie.step5.t": "Graphes",
  "methodologie.step6.d": "Apriori sur les 16 451 enfants 6-14 ans : combinaisons de facteurs menant \u00e0 l'exclusion (lift > 1.05).",
  "methodologie.step6.t": "R\u00e8gles d'association",
