  "rapport.assembling": "Assemblage du rapport\u2026",
  "rapport.cover.lead": "Qui sont les {n} enfants mauritaniens de 6-14 ans hors de l'\u00e9cole formelle ? O\u00f9 vivent-ils ? Qu'est-ce qui les exclut ? Ce rapport traduit l'enqu\u00eate EPCV 2019 en priorit\u00e9s d'investissement territorialis\u00e9es : des pourcentages aux enfants, des enfants aux d\u00e9cisions.",
  "rapport.cover.no": "Rapport n\u00b0 {n}",
  "rapport.cover.sources": "Sources : EPCV 2019 (ONS) \u00b7 projections ONS/UNFPA 2022 \u00b7 Banque mondiale WDI \u00b7 OSM \u00b7 MLN \u00b7 data.gov.mr",
  "rapport.cover.stat1": "des 6-14 ans hors \u00e9cole formelle",
  "rapport.cover.stat2": "de l'exclusion dans 5 wilayas",
  "rapport.cover.stat3": "horizon des sc\u00e9narios d'investissement",
  "rapport.cover.subtitle": "Indice de priorit\u00e9 \u00e9ducative \u00b7 Mauritanie",
  "rapport.cover.team": "R\u00e9alis\u00e9 par l'\u00e9quipe DataSphere",
  "rapport.cover.theme": "Hackathon IndabaX Mauritanie 2026 \u00b7 Th\u00e8me \u00ab Population & D\u00e9mographie \u00bb",
  "rapport.download_pdf": "T\u00e9l\u00e9charger en PDF",
  "rapport.export_badge": "Rapport \u00b7 Export PDF",
  "rapport.footer.tagline": "Les pourcentages aux enfants, les enfants aux d\u00e9cisions.",
  "rapport.intro": "Document A4 pr\u00eat \u00e0 imprimer : synth\u00e8se, classement, concentration, typologie, d\u00e9terminants, sc\u00e9narios et recommandations, illustr\u00e9s de graphiques. Astuce : \u00ab Enregistrer au format PDF \u00bb dans la bo\u00eete de dialogue.",
  "rapport.s1.box_mahadra": "En mahadra (trad. + coranique)",
  "rapport.s1.donut_title": "R\u00e9partition des exclus",
  "rapport.s1.lead1": "La Mauritanie est un pays jeune :",
  "rapport.s1.lead2": "d'habitants, dont",
  "rapport.s1.lead3": "({pct} %). Parmi eux,",
  "rapport.s1.lead4": "soit {taux} %. La moiti\u00e9 de ces enfants fr\u00e9quente une mahadra (traditionnelle ou coranique) ; l'autre moiti\u00e9 n'a",
  "rapport.s1.lead5": ". Le syst\u00e8me formel n'absorbe donc qu'un enfant sur deux de la g\u00e9n\u00e9ration scolarisable.",
  "rapport.s1.line_title": "Recul national du hors \u00e9cole primaire",
  "rapport.s1.m1.text": "Filles et gar\u00e7ons sont \u00e0 parit\u00e9 (32 % vs 34 %). En revanche, le rural double l'urbain (42 % vs 21 %) et 5 wilayas concentrent 72 % du probl\u00e8me.",
  "rapport.s1.m1.title": "L'exclusion est g\u00e9ographique, pas sexu\u00e9e.",
  "rapport.s1.m2.text": "44 % des 6-9 ans sont d\u00e9j\u00e0 hors \u00e9cole contre 23 % des 10-14 ans : l'\u00e9chec se joue \u00e0 l'entr\u00e9e dans la scolarit\u00e9, pas \u00e0 la sortie.",
  "rapport.s1.m2.title": "L'\u00e2ge de 6-9 ans est le point d'entr\u00e9e.",
  "rapport.s1.m3.text": "La moiti\u00e9 des exclus est scolaris\u00e9e ailleurs qu'\u00e0 l'\u00e9cole formelle. Convertir ce vivier est le levier le plus rentable \u00e0 2030 (\u221239 % du hors \u00e9cole en convertissant 50 %).",
  "rapport.s1.m3.title": "La mahadra est un pont, pas une impasse.",
  "rapport.s1.messages_title": "Trois messages structurants",
  "rapport.s1.p1.text": "IPE {ipe} priorit\u00e9 maximale : effort massif, volume et taux \u00e9lev\u00e9s.",
  "rapport.s1.p2.text": "IPE {ipe} premier vivier mahadra du pays ({n} enfants).",
  "rapport.s1.p3.text": "IPE {ipe} troisi\u00e8me priorit\u00e9, profil mixte mahadra + aucune instruction.",
  "rapport.s1.series_hors_ecole": "Hors \u00e9cole primaire (%)",
  "rapport.s1.series_nette": "Taux net de scolarisation (%)",
  "rapport.s1.title": "Synth\u00e8se ex\u00e9cutive",
  "rapport.s1.wdi_unavailable": "S\u00e9ries WDI indisponibles.",
  "rapport.s2.hbar_title": "Classement visuel de l'IPE",
  "rapport.s2.lead": "IPE = 40 % \u00d7 volume (log enfants hors \u00e9cole) + 35 % \u00d7 intensit\u00e9 (taux hors \u00e9cole) + 25 % \u00d7 vuln\u00e9rabilit\u00e9 (75 % pauvret\u00e9 + 25 % d\u00e9pendance jeunes). Chaque wilaya est associ\u00e9e \u00e0 un levier d'action dominant.",
  "rapport.s2.th_aucune": "Aucune instr.",
  "rapport.s2.th_levier": "Levier",
  "rapport.s2.th_rang": "Rang",
  "rapport.s2.th_taux": "Taux",
  "rapport.s2.title": "Classement : Indice de Priorit\u00e9 \u00c9ducative (IPE)",
  "rapport.s3.cible.badge": "Cible",
  "rapport.s3.cible.text": "La priorisation g\u00e9ographique permet de concentrer l'effort sur un nombre restreint de territoires.",
  "rapport.s3.cible.title": "{n} wilayas = 50 %",
  "rapport.s3.lead1": "L'exclusion n'est pas diffuse :",
  "rapport.s3.lead2": "du hors \u00e9cole formelle (top 3 : {top3} %), et {n} wilayas suffisent pour atteindre la moiti\u00e9. La courbe de Lorenz mesure cette in\u00e9galit\u00e9 (Gini : {gini}).",
  "rapport.s3.lead_bold": "5 wilayas portent {part}",
  "rapport.s3.title": "Concentration territoriale",
  "rapport.s3.top1.text": "{n} enfants hors \u00e9cole, soit {pct} % du total.",
  "rapport.s3.top5.text": "5 wilayas de l'est et du sud : Guidimakha, Hodh El Gharbi, Hodh Ech Chargui, Assaba, Brakna.",
  "rapport.s3.top5.title": "72,1 % du probl\u00e8me",
  "rapport.s4.cat_10_14": "10-14 ans",
  "rapport.s4.cat_6_9": "6-9 ans",
