  "rapport.s4.profiles_title": "Trois profils r\u00e9gionaux (k-moyennes, k = 3)",
  "rapport.s4.title": "Typologie des wilayas et d\u00e9composition de l'exclusion",
  "rapport.s5.lead": "Mod\u00e8le logistique sur {n} enfants 6-14 ans (pseudo-R\u00b2 de Nagelkerke : {r2}, AIC {aic}). Les rapports de cotes (OR) mesurent la sur-exposition au risque hors \u00e9cole par rapport \u00e0 la cat\u00e9gorie de r\u00e9f\u00e9rence.",
