  "rapport.s5.wilaya_effects": "Effets wilayas (r\u00e9f. : {ref})",
  "rapport.s6.card_base": "Base",
  "rapport.s6.card_cible1": "Cible 1",
  "rapport.s6.card_cible2": "Cible 2",
  "rapport.s6.card_offre": "Offre",
  "rapport.s6.construction_title": "Besoins de construction d'\u00e9coles de proximit\u00e9 (top wilayas)",
  "rapport.s6.enfants_taux": "enfants (taux {taux} %)",
  "rapport.s6.lead1": "La tendance mondiale du hors \u00e9cole primaire (\u22120,64 pt/an) appliqu\u00e9e \u00e0 2022-2030 laisse",
  "rapport.s6.lead2": "hors \u00e9cole formelle en 2030. Les sc\u00e9narios testent des r\u00e9ponses politiques. Hypoth\u00e8ses : population 6-14 constante ; 1 \u20ac \u2248 460 MRO ; co\u00fbt indicatif de 25 M MRO par \u00e9cole (40 \u00e9l\u00e8ves).",
  "rapport.s6.lead_bold": "{n} enfants",
  "rapport.s6.no_reduction": "pas de r\u00e9duction",
  "rapport.s6.reduction": "\u2212 {n} vs 2022",
  "rapport.s6.th_cout": "Co\u00fbt (M MRO)",
  "rapport.s6.title": "Sc\u00e9narios 2030 : combien d'enfants, \u00e0 quel co\u00fbt",
  "rapport.s7.matrix_title": "Matrice volume \u00d7 intensit\u00e9 (m\u00e9dianes nationales)",
  "rapport.s7.method_title": "M\u00e9thodologie & sources",
  "rapport.s7.quadrant_meta": "{n} enfants \u00b7 {taille} wilayas",
  "rapport.s7.src1_text": "60 600 individus, module \u00e9ducation (statut scolaire, \u00e2ge, milieu, pauvret\u00e9) pour les mod\u00e8les individuels (logit) et la d\u00e9composition.",
  "rapport.s7.src2_text": "populations par wilaya (structure par \u00e2ge 6-14).",
  "rapport.s7.src3_text": "s\u00e9ries 2000-2024 (SE.PRM.UNER.ZS, SE.PRM.NENR, etc.) pour la tendance des sc\u00e9narios.",
  "rapport.s7.src4_text": "nombre d'\u00e9tablissements par wilaya ; g\u00e9om\u00e9tries OpenStreetMap.",
  "rapport.s7.src5_name": "Mod\u00e8les",
  "rapport.s7.src5_text": "IPE pond\u00e9r\u00e9 (volume/intensit\u00e9/vuln\u00e9rabilit\u00e9), k-moyennes (silhouette, k=3), corr\u00e9lations de Pearson, r\u00e9gression logistique (statsmodels), arbres de d\u00e9cision CART pour les r\u00e8gles d'association (support, confiance, lift).",
  "rapport.s7.src6_name": "Limites",
