  "optim.dea.efficientes": "On the frontier",
  "optim.dea.convergence": "Two independent methods converge: Nouakchott is both the least efficient wilaya under DEA and the one furthest from its expected profile. Its room for progress is organisational, not budgetary.",
  "nav.parcours": "Pathways",
  "nav.rendement": "Returns",
  "parcours.loading": "Reconstructing pathways…",
  "parcours.eyebrow": "After entering school",
  "parcours.title": "Pathways & generations",
  "parcours.subtitle": "Counting the children present at school says nothing about how far they get. Level attained (C4N) and age group, available in the EPCV and never used until now, reveal a second problem: the flow.",
  "parcours.kpi.retard": "Over-age in primary",
  "parcours.kpi.retard_sub": "of the {n} pupils aged 12-14, still in primary",
  "parcours.kpi.college": "Reach lower secondary",
  "parcours.kpi.college_sub": "cohort aged 15-24",
  "parcours.kpi.superieur": "Reach higher education",
  "parcours.kpi.superieur_sub": "cohort aged 15-24",
  "parcours.kpi.generations": "Progress over three generations",
  "parcours.kpi.generations_sub": "formal access, 60+ → 15-24",
  "parcours.retard.title": "The second problem: staying in primary",
  "parcours.retard.subtitle": "Primary normally covers ages 6-11. At 12 a pupil should be in lower secondary. The share still enrolled in primary is shown above each bar.",
  "parcours.retard.primaire": "In primary",
  "parcours.retard.college": "In lower secondary",
  "parcours.retard.ans": "age {n}",
  "parcours.retard.definition": "A pupil is counted as over-age when they are at least 12 and still enrolled in primary, which normally covers ages 6-11 (six years of study).",
  "parcours.retard.rural": "Over-age, rural",
  "parcours.retard.urbain": "Over-age, urban",
  "parcours.retard.par_wilaya": "Over-age by wilaya (pupils aged 12-14)",
  "parcours.survie.title": "Educational survival: the funnel",
  "parcours.survie.subtitle": "Out of 100 young people aged 15-24, how many reached each stage? Each stage includes the ones above it: an upper-secondary pupil necessarily completed lower secondary.",
  "parcours.survie.ecarts": "Access to lower secondary by circumstance",
  "parcours.survie.milieu": "Area",
  "parcours.survie.pauvrete": "Poverty",
  "parcours.survie.genre": "Gender",
  "parcours.survie.pauvre": "poor",
  "parcours.survie.non_pauvre": "not poor",
  "parcours.survie.filles": "girls",
  "parcours.survie.garcons": "boys",
  "parcours.survie.lecture": "The urban/rural gap in access to lower secondary reaches {milieu} points, against {genre} point for the gap between boys and girls. The bottleneck in the pathway is territorial and social, not gendered — the same finding as for access.",
  "parcours.pyramide.title": "Where the flow narrows, age by age",
  "parcours.pyramide.subtitle": "Distribution by level attained from age 6 to 24. The \"never schooled\" band stops shrinking after age 10: past that age, no one enters.",
  "parcours.pyramide.age": "Age",
  "parcours.cohortes.title": "Three generations of progress",
  "parcours.cohortes.subtitle": "The 60+ were schooled around 1960-1975, the 25-59 around 1980-2000, the 15-24 around 2000-2015. One survey, three eras.",
  "parcours.cohortes.lecture": "Access to formal school rose from {a}% among those aged 60 and over to {b}% among 15-24 year-olds. Over the same period the gap between boys and girls narrowed by {g} points: the gender question was settled by the generations.",
  "parcours.cohortes.ecart_gf": "boys − girls gap",
  "parcours.rattrapage.title": "Who is catching up, who is falling behind?",
  "parcours.rattrapage.subtitle": "Formal access from the 25-59 generation to the 15-24 generation. Every wilaya progresses: what distinguishes them is progressing fast enough to catch up.",
  "parcours.rattrapage.insuffisant": "insufficient catch-up",
  "parcours.rattrapage.ok": "catching up or ahead",
  "parcours.rattrapage.lecture": "{n} wilaya(s) — {liste} — combine a level below the national average for 15-24 year-olds ({nat}%) with a gain below the median ({med} pts): their gap is widening in relative terms. This is a priority criterion that the EPI, which measures the stock, cannot capture.",
  "Jamais scolarisé": "Never schooled",
  "Traditionnel": "Traditional",
  "Préscolaire / NSP": "Pre-school / DK",
  "Primaire": "Primary",
