  "rendement.loading": "Computing returns…",
  "rendement.eyebrow": "Why invest",
  "rendement.title": "The returns to schooling",
  "rendement.subtitle": "The project argues for formal school without ever showing what it yields. Unemployment and poverty, crossed with level attained, give an answer — and it is counter-intuitive.",
  "rendement.kpi.pauvrete": "Poverty",
  "rendement.kpi.pauvrete_sub": "non-formal → formal, i.e. {n} points",
  "rendement.kpi.structure": "Own return",
  "rendement.kpi.structure_sub": "share of the gap not explained by profile",
  "rendement.kpi.chomage": "Unemployment",
  "rendement.kpi.chomage_sub": "never schooled → university",
  "rendement.kpi.or": "Poverty risk",
  "rendement.kpi.or_sub": "university vs never schooled, all else equal",
  "rendement.gradient.title": "Two opposite gradients",
  "rendement.gradient.subtitle": "The same axis of levels, two opposite results. The charts are kept separate: stacking two scales on one axis would distort the comparison.",
  "rendement.gradient.pauvrete": "Poverty rate by level attained",
  "rendement.gradient.chomage": "Unemployment rate (ILO) by level attained",
  "rendement.paradoxe.title": "The educated-unemployment paradox",
  "rendement.paradoxe.text": "Formal schooling does not lower unemployment — it raises it. This is a definitional effect: under the ILO definition, the unemployed are those seeking work. Rural and unschooled, one is occupied (farming, herding, informal work) hence not \"unemployed\", and poor. A qualification opens a labour market where one can be job-seeking — and where one is markedly less poor.",
  "rendement.oaxaca.title": "Oaxaca-Blinder decomposition",
  "rendement.oaxaca.subtitle": "Does the poverty gap come from schooling itself, or from the fact that schooled people are also more urban and younger? The decomposition separates the two.",
  "rendement.oaxaca.total": "Total gap",
  "rendement.oaxaca.composition": "Composition",
  "rendement.oaxaca.structure": "Structure",
  "rendement.oaxaca.lecture_cle": "The \"structure\" share is what a schooling programme can hope to capture: it measures the own return to schooling, at identical characteristics. The \"composition\" share is a reminder that part of the gap is about who schooled people are, not about schooling itself.",
  "rendement.oaxaca.detail": "Breakdown of the composition effect",
  "rendement.oaxaca.detail_note": "Contribution of each characteristic to the \"composition\" share, in percentage points of the poverty gap.",
  "rendement.var.rural": "Rural area",
  "rendement.var.feminin": "Female",
  "rendement.var.age": "Age",
  "rendement.var.age2": "Age²",
  "rendement.var.wilaya": "Wilaya",
  "rendement.logit.title": "Adjusted poverty risk by level attained",
  "rendement.logit.subtitle": "Poverty odds ratios, reference \"{ref}\". Controls: {controles}. A bar shorter than the dashed line means reduced risk.",
  "rendement.logit.lecture": "Estimated on {n} individuals aged 15-64, pseudo-R² of {r2}. Even at identical age, sex, area and wilaya, each stage completed lowers the poverty risk — so the gradient is not a mere composition effect.",
  "unit.pts": "pts",
  "unit.pt_an": "pt/yr",
  "robustesse.mc.conclusion": "Across {n} weighting sets drawn at random around the chosen weights, {k} of {tot} wilayas keep the same rank in 90% of draws — including the top five, which never move. Instability is confined to the middle of the ranking ({instables}), where EPI gaps are around a single point. The five aggregation methods also agree at ρ ≥ {rho} (Spearman): the hierarchy of priorities is a property of the data, not of the weighting choice.",
  "robustesse.ci.note": "Non-parametric bootstrap (simple resampling with replacement over individuals). The EPCV file provided contains no household identifier, no sampling weight and no stratum: the cluster effect is not modelled, so these intervals are an optimistic bound on the true uncertainty.",
  "robustesse.theil.lecture": "{inter}% of exclusion inequality plays out between wilayas, {intra}% within each of them (the urban/rural divide). Purely territorial targeting therefore cannot reach the whole problem.",
  "robustesse.hoi.lecture": "{c}% of children aged 6-14 have access to formal school, but once adjusted for unequal circumstances that coverage is only \"worth\" {h}%: {p} points are lost purely because access depends on where and to whom a child is born.",
  "robustesse.offre.lecture": "{db}% of facilities would have to be redeployed for supply to match the map of out-of-school children, against {de}% to match the map of children as such: supply is misaligned with need, not merely with population.",
  "robustesse.validation.explication": "The two measures do not count the same thing. The EPCV here measures 6-14 year-olds who never entered formal school (the \"dejall\" variable shows that no out-of-school child in this bracket entered and then left). The WDI measures children of official primary age out of school in a given year. A 2-point gap over a wider age bracket is consistent.",
  "robustesse.validation.alerte": "The {p1} pt/year slope that drives the 2030 scenarios rests almost entirely on the single 2024 observation ({v2024}%, against {v2020}% in 2020). Without that point the trend falls to {p2} pt/year — near stagnation. The projections must be read as a bracket between these two hypotheses, not as a forecast.",
  "robustesse.validation.uis": "The file data/raw/unesco_uis_outofschool.csv contains no data: it is the record of a failed connection to the UIS API (DNS resolution). External validation therefore rests on the WDI alone.",
  "nav.robustesse": "Robustness",
  "Wilaya": "Wilaya",
  "robustesse.loading": "Computing intervals and simulations…",
  "robustesse.eyebrow": "Statistical rigour",
  "robustesse.title": "Robustness & equity",
  "robustesse.subtitle": "A ranking is only worth what we know about its dependence on sampling noise and on the choice of weights. This page tests both, then measures inequality of opportunity.",
  "robustesse.kpi.marge": "Median margin of error",
  "robustesse.kpi.marge_sub": "bootstrap, {n} draws, 95% CI",
  "robustesse.kpi.rangs": "Stable ranks",
  "robustesse.kpi.rangs_sub": "across {n} weighting sets",
  "robustesse.kpi.spearman": "Agreement across methods",
  "robustesse.kpi.spearman_sub": "{n} aggregations compared",
  "robustesse.kpi.hoi": "Human Opportunity Index",
  "robustesse.kpi.hoi_sub": "coverage {c}%, of which {p} pts lost to inequality",
  "robustesse.mc.title": "Does the ranking depend on the weights?",
  "robustesse.mc.subtitle": "10,000 weight sets drawn at random around 0.40 / 0.35 / 0.25 (Dirichlet). The bar shows the range of ranks reached in 90% of draws.",
  "robustesse.rang_median": "Median rank",
  "robustesse.intervalle_90": "90% interval",
  "robustesse.prob_top3": "Probability of being in the top 3",
  "robustesse.rang_ipe": "EPI rank",
  "robustesse.legende.stable": "rank unchanged in 90% of draws",
  "robustesse.legende.instable": "rank sensitive to weights",
  "robustesse.ci.title": "What the sample actually supports",
  "robustesse.ci.subtitle": "Every rate is an estimate from an uneven sample: 267 children in Inchiri against 2,619 in Nouakchott. The shrunk estimator pulls small wilayas toward the national mean in proportion to their imprecision.",
  "robustesse.ci.n": "Children surveyed",
  "robustesse.ci.taux": "Out-of-school rate",
  "robustesse.ci.ic": "95% CI",
  "robustesse.ci.marge": "Margin",
