  "indicateurs.eyebrow": "Correlation matrix \u00b7 Pearson",
  "indicateurs.heatmap_sub": "Green = negative correlation, orange = positive, black = neutral. Read only the lower triangle (the image is symmetric).",
  "indicateurs.heatmap_title": "Correlation heatmap, 12 indicators \u00d7 13 wilayas",
  "indicateurs.insight1.text": "The out-of-school rate is driven by youth dependency (0-14 / 15-64), itself rooted in rurality: the large, poor rural family is the structural target.",
  "indicateurs.insight1.title": "Rurality is the foundation",
  "indicateurs.insight2.text": "The 0-14 share and youth dependency are correlated at 1.00: they are one and the same demographic determinant, to be treated as a single block.",
  "indicateurs.insight2.title": "Youth share and dependency: twins",
  "indicateurs.insight3.text": "Gender appears nowhere: it does not discriminate out-of-school status. Likewise, the number of schools is not the main lever; distance and the mahadra supply are.",
  "indicateurs.insight3.title": "What does not correlate",
  "indicateurs.insight4.text": "The r values of 1.00 come from indicators built from one another: we exclude them from the recommendations.",
  "indicateurs.insight4.title": "Beware of perfect correlations",
  "indicateurs.loading": "Computing correlations\u2026",
  "indicateurs.subtitle": "The correlation matrix of 12 indicators (Pearson r, color = strength) reveals the structural determinants. A symmetric heatmap, sorted for readability.",
  "indicateurs.title": "What drives exclusion, and what does not",
  "indicateurs.top_title": "The strongest correlations",
