  "methodologie.choix": "Methodological choices",
  "methodologie.choix1.k": "A single type of formal school",
  "methodologie.choix1.text": "The official \u00ab Quranic \u00bb category (C4N=2) is aggregated with the mahadra in line with the EduFocus framework. A child in a mahadra is \u00ab out of formal school \u00bb but educated: the effort focuses on pathways, not literacy.",
  "methodologie.choix2.k": "2019 \u2192 2022 weighting",
  "methodologie.choix2.text": "The EPCV 2019 shares are applied to the 2022 pyramids per wilaya: percentages become budgetable counts.",
  "methodologie.choix3.k": "Min-max normalization",
  "methodologie.choix3.text": "Each IPE component is normalized 0-100 before weighting, to make the three dimensions comparable.",
  "methodologie.choix4.k": "Interpretable clusters",
  "methodologie.choix4.text": "k chosen by silhouette (k=3: 0.331) for a balance between statistical readability and richness of profiles.",
  "methodologie.intensite": "Intensity",
  "methodologie.intensite.def": "Share of 6-14 year-olds out of formal school (formal excluded, mahadra and no instruction included).",
