  "rapport.assembling": "Assembling the report\u2026",
  "rapport.cover.lead": "Who are the {n} Mauritanian children aged 6-14 out of formal school? Where do they live? What excludes them? This report turns the EPCV 2019 survey into territorialised investment priorities: from percentages to children, from children to decisions.",
  "rapport.cover.no": "Report No. {n}",
  "rapport.cover.sources": "Sources: EPCV 2019 (ONS) \u00b7 ONS/UNFPA 2022 projections \u00b7 World Bank WDI \u00b7 OSM \u00b7 MLN \u00b7 data.gov.mr",
  "rapport.cover.stat1": "of 6-14 year-olds out of formal school",
  "rapport.cover.stat2": "of exclusion in 5 wilayas",
  "rapport.cover.stat3": "horizon of the investment scenarios",
  "rapport.cover.subtitle": "Educational priority index \u00b7 Mauritania",
  "rapport.cover.team": "Produced by the DataSphere team",
  "rapport.cover.theme": "IndabaX Mauritania 2026 Hackathon \u00b7 Theme \u00ab Population & Demography \u00bb",
  "rapport.download_pdf": "Download as PDF",
  "rapport.export_badge": "Report \u00b7 PDF export",
  "rapport.footer.tagline": "From percentages to children, from children to decisions.",
  "rapport.intro": "A4 document ready to print: executive summary, ranking, concentration, typology, determinants, scenarios and recommendations, illustrated with charts. Tip: \u00ab Save as PDF \u00bb in the print dialog.",
  "rapport.s1.box_mahadra": "In mahadra (trad. + Quranic)",
  "rapport.s1.donut_title": "Breakdown of the excluded",
  "rapport.s1.lead1": "Mauritania is a young country:",
  "rapport.s1.lead2": "inhabitants, including",
  "rapport.s1.lead3": "({pct}%). Among them,",
  "rapport.s1.lead4": "i.e. {taux}%. Half of these children attend a mahadra (traditional or Quranic); the other half has",
  "rapport.s1.lead5": ". The formal system thus absorbs only one child in two of the school-age generation.",
  "rapport.s1.line_title": "National decline in out-of-school primary",
  "rapport.s1.m1.text": "Girls and boys are at parity (32% vs 34%). Yet rural doubles urban (42% vs 21%) and 5 wilayas concentrate 72% of the problem.",
  "rapport.s1.m1.title": "Exclusion is geographic, not gendered.",
  "rapport.s1.m2.text": "44% of 6-9 year-olds are already out of school versus 23% of 10-14 year-olds: failure is decided at entry into schooling, not at exit.",
  "rapport.s1.m2.title": "Age 6-9 is the entry point.",
  "rapport.s1.m3.text": "Half of the excluded are schooled outside formal school. Converting this pool is the most cost-effective lever by 2030 (\u221239% of out-of-school children by converting 50%).",
  "rapport.s1.m3.title": "The mahadra is a bridge, not a dead end.",
  "rapport.s1.messages_title": "Three key messages",
  "rapport.s1.p1.text": "IPE {ipe} maximum priority: mass effort, high volume and rate.",
  "rapport.s1.p2.text": "IPE {ipe} the country's leading mahadra pool ({n} children).",
  "rapport.s1.p3.text": "IPE {ipe} third priority, mixed mahadra + no-instruction profile.",
  "rapport.s1.series_hors_ecole": "Out-of-school primary (%)",
  "rapport.s1.series_nette": "Net enrolment rate (%)",
  "rapport.s1.title": "Executive summary",
  "rapport.s1.wdi_unavailable": "WDI series unavailable.",
  "rapport.s2.hbar_title": "Visual IPE ranking",
  "rapport.s2.lead": "IPE = 40% \u00d7 volume (log of out-of-school children) + 35% \u00d7 intensity (out-of-school rate) + 25% \u00d7 vulnerability (75% poverty + 25% youth dependency). Each wilaya is associated with a dominant action lever.",
  "rapport.s2.th_aucune": "No instr.",
  "rapport.s2.th_levier": "Lever",
  "rapport.s2.th_rang": "Rank",
  "rapport.s2.th_taux": "Rate",
  "rapport.s2.title": "Ranking: Educational Priority Index (IPE)",
  "rapport.s3.cible.badge": "Target",
  "rapport.s3.cible.text": "Geographic prioritisation concentrates effort on a limited number of territories.",
  "rapport.s3.cible.title": "{n} wilayas = 50%",
  "rapport.s3.lead1": "Exclusion is not diffuse:",
  "rapport.s3.lead2": "of out-of-school formal education (top 3: {top3}%), and {n} wilayas are enough to reach half. The Lorenz curve measures this inequality (Gini: {gini}).",
  "rapport.s3.lead_bold": "5 wilayas carry {part}",
  "rapport.s3.title": "Territorial concentration",
