  "rendement.subtitle": "يدافع المشروع عن المدرسة النظامية دون أن يبيّن قط ما تدرّه. متغيرا البطالة والفقر، مقاطَعين بالمستوى المحقق، يقدمان جواباً — وهو مخالف للحدس.",
