  "rendement.gradient.title": "تدرجان متعاكسان",
  "rendement.gradient.subtitle": "المحور نفسه للمستويات، ونتيجتان متعاكستان. الرسمان منفصلان عمداً: جمع مقياسين على محور واحد يشوّه المقارنة.",
  "rendement.gradient.pauvrete": "نسبة الفقر حسب المستوى المحقق",
  "rendement.gradient.chomage": "نسبة البطالة (منظمة العمل) حسب المستوى المحقق",
  "rendement.paradoxe.title": "مفارقة بطالة المتعلمين",
  "rendement.paradoxe.text": "لا تخفض المدرسة النظامية البطالة بل ترفعها. وهذا أثر تعريفي: العاطل وفق منظمة العمل الدولية هو الباحث عن عمل. ففي الريف ودون تعليم يكون المرء مشغولاً (زراعة، رعي، قطاع غير منظم) فلا يُحسب «عاطلاً»، ويكون فقيراً. الشهادة تُدخل سوق عمل يمكن أن يكون فيها المرء باحثاً — وفيها يكون أقل فقراً بكثير.",
  "rendement.oaxaca.title": "تفكيك أوكساكا-بلايندر",
  "rendement.oaxaca.subtitle": "هل تأتي فجوة الفقر من التعليم نفسه، أم من كون المتعلمين أكثر تحضراً وأصغر سناً؟ التفكيك يفصل بين الأمرين.",
  "rendement.oaxaca.total": "الفارق الإجمالي",
  "rendement.oaxaca.composition": "التركيبة",
  "rendement.oaxaca.structure": "البنية",
  "rendement.oaxaca.lecture_cle": "حصة «البنية» هي ما يمكن لبرنامج تمدرس أن يأمل في التقاطه: تقيس العائد الذاتي للتعليم عند تساوي الخصائص. أما حصة «التركيبة» فتذكّر بأن جزءاً من الفارق يعود إلى هوية المتعلمين لا إلى التعليم ذاته.",
  "rendement.oaxaca.detail": "تفصيل أثر التركيبة",
  "rendement.oaxaca.detail_note": "مساهمة كل خاصية في حصة «التركيبة»، بنقاط مئوية من فجوة الفقر.",
  "rendement.var.rural": "الوسط الريفي",
  "rendement.var.feminin": "أنثى",
  "rendement.var.age": "العمر",
  "rendement.var.age2": "العمر²",
  "rendement.var.wilaya": "الولاية",
  "rendement.logit.title": "خطر الفقر المعدَّل حسب المستوى المحقق",
  "rendement.logit.subtitle": "نسب الأرجحية للفقر، المرجع «{ref}». الضوابط: {controles}. عمود أقصر من الخط المتقطع يعني خطراً أقل.",
  "rendement.logit.lecture": "مقدَّر على {n} فرداً بين 15 و64 سنة، بمعامل تحديد زائف {r2}. حتى عند تساوي العمر والجنس والوسط والولاية، كل مرحلة مقطوعة تخفض خطر الفقر — فالتدرج ليس مجرد أثر تركيبة.",
  "unit.pts": "نقطة",
  "unit.pt_an": "نقطة/سنة",
  "robustesse.mc.conclusion": "عبر {n} مجموعة أوزان مسحوبة عشوائياً حول الأوزان المعتمدة، تحتفظ {k} ولاية من أصل {tot} بالمرتبة نفسها في 90٪ من السحوبات — ومنها الخمس الأولى التي لا تتحرك أبداً. ينحصر عدم الاستقرار في وسط الترتيب ({instables}) حيث الفوارق في المؤشر بحدود نقطة واحدة. كما تتوافق طرق التجميع الخمس عند ρ ≥ {rho} (سبيرمان): تسلسل الأولويات خاصية من خصائص البيانات لا من اختيار الأوزان.",
  "robustesse.ci.note": "بوتستراب لا معلمي (سحب بسيط مع الإرجاع على الأفراد). لا يتضمن ملف المسح المقدَّم معرّف أسرة ولا أوزان سحب ولا طبقات: أثر التجمّع غير منمذج، لذا تمثّل هذه الفترات حداً متفائلاً لعدم اليقين الفعلي.",
  "robustesse.theil.lecture": "{inter}٪ من لامساواة الاستبعاد تدور بين الولايات، و{intra}٪ داخل كل منها (الفجوة الحضرية الريفية). لذلك لا يمكن للاستهداف الجغرافي وحده أن يبلغ كامل المشكلة.",
  "robustesse.hoi.lecture": "{c}٪ من الأطفال بين 6 و14 سنة يلجون المدرسة النظامية، لكن هذه التغطية بعد تصحيحها بعدم تكافؤ الظروف لا «تساوي» سوى {h}٪: تضيع {p} نقطة لمجرد أن الولوج يتوقف على مكان الولادة وعلى الأسرة.",
  "robustesse.offre.lecture": "يلزم إعادة توزيع {db}٪ من المؤسسات لكي يطابق العرضُ خريطةَ الأطفال خارج المدرسة، مقابل {de}٪ لمطابقة خريطة الأطفال عموماً: العرض غير متوائم مع الحاجة، لا مع السكان فحسب.",
  "robustesse.validation.explication": "المقياسان لا يحصيان الشيء نفسه. يقيس المسح هنا الأطفال من 6 إلى 14 سنة الذين لم يلجوا المدرسة النظامية قط (يبيّن متغير «dejall» أن أي طفل خارج المدرسة في هذه الفئة لم يلجها ثم يغادرها). أما WDI فيقيس أطفال سن الابتدائي الرسمي خارج المدرسة في سنة معينة. وفارق نقطتين على فئة عمرية أوسع أمر متسق.",
  "robustesse.validation.alerte": "الميل البالغ {p1} نقطة سنوياً الذي تقوم عليه سيناريوهات 2030 يستند شبه كلياً إلى ملاحظة 2024 وحدها ({v2024}٪ مقابل {v2020}٪ سنة 2020). وبدون هذه النقطة يهبط الاتجاه إلى {p2} نقطة سنوياً، أي شبه ركود. لذا تُقرأ الإسقاطات بوصفها مجالاً بين هاتين الفرضيتين لا تنبؤاً.",
  "robustesse.validation.uis": "لا يحتوي ملف data/raw/unesco_uis_outofschool.csv على أي بيانات: إنه أثر فشل اتصال بواجهة UIS (تعذر تحليل DNS). لذا يعتمد التحقق الخارجي على WDI وحده.",
