  "Atteindre 1 \u00e9tablissement pour 1 000 enfants dans chaque wilaya (densit\u00e9 actuelle : 0,59/1000 au niveau national).": "\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0645\u0624\u0633\u0633\u0629 \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0648\u0627\u062d\u062f\u0629 \u0644\u0643\u0644 1000 \u0637\u0641\u0644 \u0641\u064a \u0643\u0644 \u0648\u0644\u0627\u064a\u0629 (\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629: 0,59/1000 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0648\u0637\u0646\u064a).",
  "Aucune instruction": "\u0628\u062f\u0648\u0646 \u062a\u0639\u0644\u064a\u0645",
