  "Base": "\u0627\u0644\u0623\u0633\u0627\u0633",
  "Beaucoup d'enfants et un taux \u00e9lev\u00e9 : le double fardeau. Priorit\u00e9 absolue de construction et de recrutement.": "\u0623\u0639\u062f\u0627\u062f \u0643\u0628\u064a\u0631\u0629 \u0645\u0646 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0645\u0639 \u0646\u0633\u0628\u0629 \u0645\u0631\u062a\u0641\u0639\u0629: \u0627\u0644\u0639\u0628\u0621 \u0627\u0644\u0645\u0632\u062f\u0648\u062c. \u0623\u0648\u0644\u0648\u064a\u0629 \u0642\u0635\u0648\u0649 \u0644\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u062a\u0639\u064a\u064a\u0646.",
  "Adultes sans instruction": "\u0628\u0627\u0644\u063a\u0648\u0646 \u0628\u0644\u0627 \u062a\u0639\u0644\u064a\u0645",
  "Adultes 15+ sans instruction (%)": "\u0627\u0644\u0628\u0627\u0644\u063a\u0648\u0646 15+ \u0628\u0644\u0627 \u062a\u0639\u0644\u064a\u0645 (%)",
  "Ch\u00f4mage (%)": "\u0627\u0644\u0628\u0637\u0627\u0644\u0629 (%)",
  "Ciblage des effectifs": "\u0627\u0633\u062a\u0647\u062f\u0627\u0641 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0644\u062a\u062d\u0642\u0629",
  "Consolidation": "\u062a\u0648\u0637\u064a\u062f",
  "Consolider / suivre": "\u062a\u0639\u0632\u064a\u0632 / \u0645\u062a\u0627\u0628\u0639\u0629",
  "Consolider et suivre": "\u062a\u0639\u0632\u064a\u0632 \u0648\u0645\u062a\u0627\u0628\u0639\u0629",
  "Construction": "\u0627\u0644\u0628\u0646\u0627\u0621",
  "Construction d'\u00e9coles de proximit\u00e9": "\u0628\u0646\u0627\u0621 \u0645\u062f\u0627\u0631\u0633 \u0642\u0631\u064a\u0628\u0629",
  "Construire des \u00e9coles": "\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u062f\u0627\u0631\u0633",
  "Convertir la moiti\u00e9 des enfants en \u00e9ducation traditionnelle vers le formel d'ici 2030.": "\u062a\u062d\u0648\u064a\u0644 \u0646\u0635\u0641 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a \u0625\u0644\u0649 \u0627\u0644\u0646\u0638\u0627\u0645\u064a \u0628\u062d\u0644\u0648\u0644 2030.",
  "Convertir un quart des enfants en \u00e9ducation traditionnelle vers le formel d'ici 2030.": "\u062a\u062d\u0648\u064a\u0644 \u0631\u0628\u0639 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a \u0625\u0644\u0649 \u0627\u0644\u0646\u0638\u0627\u0645\u064a \u0628\u062d\u0644\u0648\u0644 2030.",
  "De grands viviers d'enfants avec un taux mod\u00e9r\u00e9 : l'effort se porte sur la conversion des effectifs (passerelles, r\u00e9tention).": "\u062e\u0632\u0627\u0646\u0627\u062a \u0643\u0628\u064a\u0631\u0629 \u0645\u0646 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0628\u0646\u0633\u0628\u0629 \u0645\u0639\u062a\u062f\u0644\u0629: \u064a\u062a\u0631\u0643\u0651\u0632 \u0627\u0644\u062c\u0647\u062f \u0639\u0644\u0649 \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0644\u062a\u062d\u0642\u0629 (\u0645\u0633\u0627\u0631\u0627\u062a\u060c \u0627\u0633\u062a\u0628\u0642\u0627\u0621).",
  "D\u00e9pendance jeunes": "\u0625\u0639\u0627\u0644\u0629 \u0627\u0644\u0634\u0628\u0627\u0628",
  "Effectif hors \u00e9cole (\u221a)": "\u0639\u062f\u062f \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629 (\u221a)",
  "Effectifs et taux contenus : maintenir, suivre les flux et pr\u00e9venir tout recul de la scolarisation.": "\u0623\u0639\u062f\u0627\u062f \u0648\u0646\u0633\u0628 \u0645\u0636\u0628\u0648\u0637\u0629: \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0648\u0636\u0639\u060c \u0648\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u062a\u062f\u0641\u0642\u0627\u062a\u060c \u0648\u0645\u0646\u0639 \u0623\u064a \u062a\u0631\u0627\u062c\u0639 \u0641\u064a \u0627\u0644\u0627\u0644\u062a\u062d\u0627\u0642.",
  "Effort massif": "\u062c\u0647\u062f \u0648\u0627\u0633\u0639 \u0627\u0644\u0646\u0637\u0627\u0642",
  "Enfants 6-14 ans": "\u0627\u0644\u0623\u0637\u0641\u0627\u0644 6-14 \u0633\u0646\u0629",
  "Enseignement traditionnel": "\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a",
  "Exclusion \u00e0 dominante 'aucune instruction'": "\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0630\u0648 \u0637\u0627\u0628\u0639 '\u0628\u062f\u0648\u0646 \u062a\u0639\u0644\u064a\u0645' \u063a\u0627\u0644\u0628",
  "Exclusion \u00e0 dominante traditionnelle": "\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0630\u0648 \u0637\u0627\u0628\u0639 \u062a\u0642\u0644\u064a\u062f\u064a \u063a\u0627\u0644\u0628",
  "Formel": "\u0631\u0633\u0645\u064a",
  "Hors \u00e9cole formelle": "\u062e\u0627\u0631\u062c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a",
  "Mahadra / Coranique": "\u0645\u062d\u0636\u0631\u0629 / \u0642\u0631\u0622\u0646\u064a\u0629",
  "Mahadra / coranique (%)": "\u0627\u0644\u0645\u062d\u0636\u0631\u0629 / \u0627\u0644\u0642\u0631\u0622\u0646\u064a\u0629 (%)",
  "Part 0-14 ans": "\u062d\u0635\u0629 \u0627\u0644\u0641\u0626\u0629 0-14 \u0633\u0646\u0629",
  "Part rurale": "\u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0631\u064a\u0641\u064a\u0629",
  "Passerelles 25 %": "\u0645\u0645\u0631\u0627\u062a 25%",
  "Passerelles 50 %": "\u0645\u0645\u0631\u0627\u062a 50%",
  "Passerelles mahadra \u2192 formel": "\u062c\u0633\u0648\u0631 \u0645\u0646 \u0627\u0644\u0645\u062d\u0636\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a",
  "Passerelles mahadra \u2192 formel (25 %)": "\u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u062d\u0627\u0636\u0631 \u2192 \u0627\u0644\u0646\u0638\u0627\u0645\u064a (25 %)",
  "Passerelles mahadra \u2192 formel (50 %)": "\u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u062d\u0627\u0636\u0631 \u2192 \u0627\u0644\u0646\u0638\u0627\u0645\u064a (50 %)",
  "Passerelles vers le formel": "\u062c\u0633\u0648\u0631 \u0646\u062d\u0648 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a",
  "Pauvret\u00e9 (%)": "\u0627\u0644\u0641\u0642\u0631 (%)",
  "Petits effectifs mais forte exclusion : solutions de proximit\u00e9, mahadra \u00e0 int\u00e9grer, suivi cibl\u00e9 des zones \u00e0 risque.": "\u0623\u0639\u062f\u0627\u062f \u0635\u063a\u064a\u0631\u0629 \u0644\u0643\u0646 \u0625\u0642\u0635\u0627\u0621 \u0642\u0648\u064a: \u062d\u0644\u0648\u0644 \u0645\u062d\u0644\u064a\u0629\u060c \u0648\u0625\u062f\u0645\u0627\u062c \u0627\u0644\u0645\u062d\u0627\u0636\u0631\u060c \u0648\u0645\u062a\u0627\u0628\u0639\u0629 \u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0644\u0644\u0645\u0646\u0627\u0637\u0642 \u0639\u0627\u0644\u064a\u0629 \u0627\u0644\u062e\u0637\u0648\u0631\u0629.",
  "Population 0-14 (%)": "\u0627\u0644\u0633\u0643\u0627\u0646 0-14 (%)",
  "Population 2022": "\u0627\u0644\u0633\u0643\u0627\u0646 2022",
  "Renforcer la r\u00e9tention scolaire": "\u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0645\u062a\u0645\u062f\u0631\u0633\u064a\u0646",
  "Ruralit\u00e9 (%)": "\u0627\u0644\u0631\u064a\u0641\u064a\u0629 (%)",
  "Scolarisation proche de l'universel": "\u062a\u0639\u0645\u064a\u0645 \u0634\u0628\u0647 \u0643\u0627\u0645\u0644 \u0644\u0644\u062a\u0645\u062f\u0631\u0633",
  "Taux de ch\u00f4mage": "\u0646\u0633\u0628\u0629 \u0627\u0644\u0628\u0637\u0627\u0644\u0629",
  "Taux de pauvret\u00e9": "\u0646\u0633\u0628\u0629 \u0627\u0644\u0641\u0642\u0631",
  "Taux hors \u00e9cole formelle": "\u0646\u0633\u0628\u0629 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a",
  "Traitement local": "\u0645\u0639\u0627\u0644\u062c\u0629 \u0645\u062d\u0644\u064a\u0629",
  "Trajectoire tendancielle": "\u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u064a \u0627\u0644\u062d\u0627\u0644\u064a",
