  "carte.subtitle": "\u0627\u0633\u062a\u0643\u0634\u0641 \u0643\u0644 \u0648\u0644\u0627\u064a\u0629 \u062d\u0633\u0628 \u0627\u0644\u0645\u0624\u0634\u0631: \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629\u060c \u0648\u0645\u0639\u062f\u0644 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629\u060c \u0648\u0627\u0644\u0641\u0642\u0631\u060c \u0648\u0627\u0644\u062f\u064a\u0645\u0648\u063a\u0631\u0627\u0641\u064a\u0627. \u0645\u0631\u0651\u0631 \u0641\u0648\u0642 \u0627\u0644\u0648\u0644\u0627\u064a\u0629 \u0644\u0639\u0631\u0636 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0648\u062c\u0632\u0629.",
