  "clusters.bar_mahadra": "\u0645\u062d\u0636\u0631\u0629 / \u0642\u0631\u0622\u0646\u064a\u0629",
  "clusters.c0_desc": "\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0645\u062a\u0628\u0642\u064d\u0651 \u0648\u062d\u0636\u0631\u064a: \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a \u0647\u0648 \u0627\u0644\u0642\u0627\u0639\u062f\u0629\u060c \u0648\u0644\u0645 \u064a\u0628\u0642\u064e \u0625\u0644\u0627 \u0627\u0644\u062a\u0639\u0632\u064a\u0632 \u0648\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629.",
  "clusters.c1_desc": "\u064a\u0645\u0631 \u0627\u0644\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0623\u0648\u0644\u064b\u0627 \u0639\u0628\u0631 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a (\u0627\u0644\u0645\u062d\u0636\u0631\u0629): \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0644\u064a\u0633\u062a \u0646\u0642\u0635 \u0627\u0644\u0645\u062f\u0627\u0631\u0633 \u0628\u0644 \u063a\u064a\u0627\u0628 \u062c\u0633\u0648\u0631 \u0646\u062d\u0648 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a.",
