  "home.fact1.k": "\u062d\u0642\u064a\u0642\u0629 1",
  "home.fact1.text": "{part} \u0645\u0646 \u0623\u0635\u0644 {total} \u0637\u0641\u0644\u064b\u0627 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u064a\u0639\u064a\u0634\u0648\u0646 \u0641\u064a 5 \u0648\u0644\u0627\u064a\u0627\u062a (\u062c\u064a\u0646\u064a {gini}). \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062c\u063a\u0631\u0627\u0641\u064a \u0636\u064a\u0651\u0642: \u062a\u0643\u0641\u064a {n} \u0648\u0644\u0627\u064a\u0627\u062a \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0646\u0635\u0641.",
  "home.fact1.title": "5 \u0648\u0644\u0627\u064a\u0627\u062a \u062a\u062d\u0645\u0644 72% \u0645\u0646 \u0627\u0644\u0645\u0634\u0643\u0644\u0629",
  "home.fact2.k": "\u062d\u0642\u064a\u0642\u0629 2",
  "home.fact2.text": "\u0645\u0639 \u062a\u0633\u0627\u0648\u064a \u0627\u0644\u062e\u0635\u0627\u0626\u0635\u060c \u064a\u0636\u0627\u0639\u0641 \u0639\u0645\u0631 6-9 \u0633\u0646\u0648\u0627\u062a \u0627\u062d\u062a\u0645\u0627\u0644 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0628\u0645\u0642\u062f\u0627\u0631 {or1} (OR {or2}, p {p}). \u064a\u064f\u062d\u0633\u0645 \u0627\u0644\u0645\u0635\u064a\u0631 \u0639\u0646\u062f \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u062f\u0631\u0633\u0629.",
  "home.fact2.title": "\u0639\u0645\u0631 6-9 \u0633\u0646\u0648\u0627\u062a \u064a\u0636\u0627\u0639\u0641 \u0627\u0644\u062e\u0637\u0631 \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a",
  "home.fact3.k": "\u062d\u0642\u064a\u0642\u0629 3",
  "home.fact3.text": "\u064a\u0647\u064a\u0645\u0646 \u0627\u0644\u0648\u0633\u0637 \u0627\u0644\u0631\u064a\u0641\u064a (OR {or1}) \u0648\u0641\u0642\u0631 \u0627\u0644\u0623\u0633\u0631\u0629 (OR {or2}). \u0627\u0644\u062c\u0646\u062f\u0631 \u0645\u062d\u0627\u064a\u062f: \u0627\u0644\u0628\u0646\u0627\u062a \u0644\u0633\u0646 \u0623\u0643\u062b\u0631 \u0627\u0633\u062a\u0628\u0639\u0627\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0623\u0648\u0644\u0627\u062f.",
