  "home.subtitle": "\u0645\u0648\u0631\u064a\u062a\u0627\u0646\u064a\u0627 \u0628\u0644\u062f \u0634\u0627\u0628: {taux} \u0645\u0646 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0645\u0646 \u0641\u0626\u0629 6-14 \u0633\u0646\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0645\u064a. \u0646\u062d\u0648\u0651\u0644 \u0627\u0644\u0646\u0633\u0628 \u0627\u0644\u0645\u0626\u0648\u064a\u0629 \u0625\u0644\u0649 \u0623\u0637\u0641\u0627\u0644\u060c \u0648\u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0625\u0644\u0649 \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0633\u062a\u062b\u0645\u0627\u0631.",
