  "regles.top_confiance.title": "\u0623\u0648\u0636\u062d \u0627\u0644\u0623\u0646\u0645\u0627\u0637: \u0645\u0646 \u0627\u0644\u0645\u062a\u0623\u062b\u0631\u061f",
  "regles.subtitle": "\u062a\u0646\u0642\u064a\u0628 \u0641\u064a \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0639\u0644\u0649 16\u066c451 \u0637\u0641\u0644\u064b\u0627 \u062a\u062a\u0631\u0627\u0648\u062d \u0623\u0639\u0645\u0627\u0631\u0647\u0645 \u0628\u064a\u0646 6 \u064814 \u0633\u0646\u0629 \u0645\u0646 \u0645\u0633\u062d EPCV 2019: \u0623\u064a\u0651 \u062a\u0648\u0644\u064a\u0641\u0627\u062a \u0645\u0646 \u0627\u0644\u0639\u0648\u0627\u0645\u0644 \u062a\u0642\u0648\u062f \u0628\u0634\u0643\u0644 \u0623\u0643\u062b\u0631 \u0645\u0648\u062b\u0648\u0642\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u061f",
