  "reseau.enfants": "\u0637\u0641\u0644\u0627\u064b",
  "reseau.hub_text": "\u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0627\u0644\u0623\u0643\u062b\u0631 \u0627\u0631\u062a\u0628\u0627\u0637\u064b\u0627 \u062a\u062a\u0634\u0627\u0631\u0643 \u0646\u0645\u0637 \u0627\u0644\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0627\u0644\u0623\u0643\u062b\u0631 \u0627\u0646\u062a\u0634\u0627\u0631\u064b\u0627: \u0647\u064a \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0645\u0631\u062c\u0639\u064a\u0629 \u0644\u0644\u0628\u0644\u0627\u062f.",
