  "reseau.lienfort_text": "{a} \u0648{b} \u0647\u0645\u0627 \u0623\u0642\u0631\u0628 \u0648\u0644\u0627\u064a\u062a\u064a\u0646 \u062f\u0631\u0627\u0633\u064a\u064b\u0651\u0627 (r = {r}): \u0628\u0639\u064a\u062f\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u062e\u0631\u064a\u0637\u0629\u060c \u0645\u062a\u0637\u0627\u0628\u0642\u062a\u0627\u0646 \u0641\u064a \u0627\u0644\u0635\u0641.",
