  "reseau.insight1_title": "\u0627\u0644\u062c\u0646\u062f\u0631 \u0644\u064a\u0633 \u0647\u0648 \u0627\u0644\u0639\u0627\u0645\u0644",
  "reseau.insight2_text": "\u062a\u0631\u062a\u0628\u0637 \u0646\u0633\u0628\u0629 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0628\u0640 {r} \u0645\u0639 \u0625\u0639\u0627\u0644\u0629 \u0627\u0644\u0634\u0628\u0627\u0628 (\u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u062f\u0648\u0631\u0647\u0627 \u0628\u0627\u0644\u0631\u064a\u0641\u064a\u0629 \u0628\u0640 {r2}): \u0627\u0644\u0647\u062f\u0641 \u0647\u0648 \u0627\u0644\u0623\u0633\u0631\u0629 \u0627\u0644\u0631\u064a\u0641\u064a\u0629 \u0627\u0644\u0634\u0627\u0628\u0629 \u0627\u0644\u0641\u0642\u064a\u0631\u0629.",
  "reseau.insight2_title": "\u0627\u0644\u0631\u064a\u0641\u064a\u0629 \u062a\u062a\u062d\u0643\u0645 \u0641\u064a \u0643\u0644 \u0634\u064a\u0621",
  "reseau.insight3_text": "\u064a\u0634\u0643\u0644 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0642\u0631 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0633\u062a\u0642\u0644\u0629: \u063a\u0646\u064a\u0629 \u0623\u0648 \u0641\u0642\u064a\u0631\u0629\u060c \u0643\u0644 \u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0644\u062f\u064a\u0647\u0627 \u0646\u0633\u0628\u0629 \u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0648\u0627\u0644\u0641\u0631\u0642 \u0647\u0648 \u0627\u0644\u0646\u0648\u0639 \u0641\u0642\u0637.",
