  "reseau.subtitle": "\u0645\u062e\u0637\u0637\u0627\u0646 \u0645\u062a\u0643\u0627\u0645\u0644\u0627\u0646: \u0627\u0644\u062a\u0634\u0627\u0628\u0647 \u0628\u064a\u0646 \u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a (\u0645\u0646 \u064a\u0634\u0628\u0647 \u0645\u0646) \u0648\u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u0624\u0634\u0631\u0627\u062a (\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u0641\u0633\u0631 \u0627\u0644\u0627\u0633\u062a\u0628\u0639\u0627\u062f).",
