  "sexe_feminin": "\u0623\u0646\u062b\u0649",
  "strategies.badge": "4 \u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a \u00b7 \u062a\u0643\u0644\u0641\u0629 25 M MRO / \u0645\u062f\u0631\u0633\u0629",
  "strategies.concentration": "\u0627\u0644\u062a\u0631\u0643\u064a\u0632",
