  "strategies.constructionsText": "\u0628\u0633\u0639\u0629 40 \u062a\u0644\u0645\u064a\u0630\u064b\u0627 / \u0645\u062f\u0631\u0633\u0629\u060c \u0648\u0647\u062f\u0641 \u0645\u062f\u0631\u0633\u062a\u064a\u0646 \u0644\u0643\u0644 1000 \u0637\u0641\u0644 (\u0627\u0644\u0645\u0631\u062c\u0639 \u0627\u0644\u062f\u0648\u0644\u064a \u0646\u062d\u0648 \u0645\u062f\u0631\u0633\u0629 \u0648\u0627\u062d\u062f\u0629 \u0644\u0643\u0644 500). \u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u062a\u0642\u062f\u064a\u0631\u064a\u0629: 25 M MRO / \u0645\u062f\u0631\u0633\u0629.",
