  "strategies.loading": "\u062c\u0627\u0631\u064d \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0635\u0641\u0648\u0641\u0629 \u0648\u0627\u0644\u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a\u2026",
