  "strategies.matriceText": "\u0639\u0644\u0649 \u0645\u062d\u0648\u0631 \u0627\u0644\u0633\u064a\u0646\u0627\u062a\u060c \u062d\u062c\u0645 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629 (\u0644\u0648\u063a\u0627\u0631\u064a\u062a\u0645)\u061b \u0648\u0639\u0644\u0649 \u0645\u062d\u0648\u0631 \u0627\u0644\u0635\u0627\u062f\u0627\u062a\u060c \u0627\u0644\u0646\u0633\u0628\u0629. \u062a\u0642\u0633\u0651\u0645 \u0627\u0644\u0648\u0633\u064a\u0637\u0627\u062a \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0627\u0644\u062e\u0631\u064a\u0637\u0629 \u0625\u0644\u0649 \u0623\u0631\u0628\u0639 \u0645\u0646\u0627\u0637\u0642 \u0644\u0644\u062a\u062f\u062e\u0644.",
